import {educationCostEvidence} from './education-cost-evidence.js?v=0.31.0';
import {careers} from './finance-data.js?v=0.31.0';
import {escapeHTML as h} from './model.js?v=0.31.0';
const usd=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(n);
const amount=a=>a.value!==undefined?usd(a.value):`${usd(a.min)}–${usd(a.max)}`;
export function needsFurtherStudy(id){return careers.find(c=>c.id===id)?.credentialLevel==='graduate'||id==='clinical-psychologist';}
export function clinicalTrainingTimeline(id){const rows=id==='physician'?[['College','About 4 years'],['MD or DO','About 4 years'],['Paid residency','Usually 3 years in family medicine']]:id==='dentist'?[['College preparation','Usually 4 years'],['DDS or DMD','Usually 4 years']]:id==='electrician'?[['Paid apprenticeship','Austin ETA: 4 years'],['Work experience','8,000 hours'],['Qualified work','Texas license + required exam']]:[];return rows.length?`<section class="training-timeline" aria-label="Typical preparation after high school">${rows.map(([title,time])=>`<article><strong>${title}</strong><span>${time}</span></article>`).join('')}</section><p>${id==='physician'?'About 11 years after high school for this common family medicine route. Other specialties differ.':id==='electrician'?'Apprentice pay comes first. Qualified electrician wages describe a later stage. College technical or business courses can add options.':'About 8 years on a common route. Some dental schools admit with fewer undergraduate credits; specialties add study.'}</p>`:'';}
export function professionalCostPanel(id){
 if(!needsFurtherStudy(id))return '';const specific=educationCostEvidence[id],e=specific||educationCostEvidence.genericGraduate,a=e.amounts;
 const key={physician:'tuitionFeesResident',dentist:'firstYearTotalResident',law:'totalResident',pharmacy:'fallSpringTuitionResident','physician-assistant':'year1TuitionFeesResident','occupational-therapy':'year1TuitionFeesResident','physical-therapy':'tuitionFeesResident12Credit','clinical-psychologist':'annualStipendMinimum',veterinary:'firstYearTotalResident'}[id]||'tuitionResident',featured=a[key]||a[Object.keys(a)[0]];
 const title=specific?e.program:'Further study after college',scope=specific?featured.label:'Generic graduate tuition reference · not this program’s price';
 return `<section class="education-evidence"><span class="evidence-source-label">${specific?h(e.label):'Published reference · program price varies'}</span><h3>${h(title)}</h3><strong class="cost-amount">${amount(featured)}</strong><span class="cost-scope">${h(scope)}</span><p>${h(specific?e.institution:e.institution+' · generic graduate reference')}</p><p>${h(featured.scope)}</p>${id==='physician'?'<p><strong>Living costs are extra. College comes before this.</strong></p>':''}${!specific?'<p>This is a comparison point for further-study planning. It does not price this credential or establish that the university offers it.</p>':''}${['old','undated','funding'].includes(e.status)?`<p><strong>${h(e.academicYear)}</strong>${e.status==='funding'?' · Funding depends on admission, appointment, and progress.':''}</p>`:`<p>${h(e.academicYear)} · Before aid${e.status==='derived'?' · Derived from published semester rates':''}</p>`}<details class="more-info"><summary>What this amount includes</summary><div><p>${h(e.note)}</p>${Object.values(a).map(v=>`<p><strong>${h(v.label)}: ${amount(v)}</strong><br>${h(v.scope)}</p>`).join('')}${e.yearRows?.length?`<h4>Other program years</h4>${e.yearRows.map(r=>`<p><strong>${r.programYear?'Year '+r.programYear:h(r.stage||'Continuing')}: ${usd(r.totalResident??r.tuitionFeesResident)}</strong> · ${r.totalResident?'total attendance budget':'tuition and fees'} · Texas resident</p>`).join('')}`:''}${(e.limitations||[]).map(t=>`<p>${h(t)}</p>`).join('')}<p>${e.sourceURLs.map((url,i)=>`<a href="${h(url)}" target="_blank" rel="noopener noreferrer">Official program source ${i+1} ↗</a>`).join(' · ')}</p><p>Checked ${h(e.checkedAt||'2026-10-16')}. Training may be outside Austin; Austin living costs apply to the later career illustration.</p></div></details></section>`;
}
export function graduateAidPanel(id){if(!needsFurtherStudy(id))return '';return `<details class="more-info"><summary>How further study can be funded</summary><div><p>Undergraduate tuition support does not automatically pay for graduate or professional school. Pell is generally for undergraduate study. Scholarships, assistantships, and loans have different terms.</p><p>For new borrowers from July 2026, Grad PLUS is generally unavailable. Published Direct loan limits differ: graduate study $20,500 per year and $100,000 in aggregate; qualifying professional study $50,000 per year and $200,000 in aggregate. The overall lifetime cap is $257,500. Program classification and limited legacy exceptions matter; these are borrowing caps, not an aid offer.</p><p><a href="https://studentaid.gov/announcements-events/big-updates" target="_blank" rel="noopener noreferrer">Current Federal Student Aid rules ↗</a> · <a href="https://fsapartners.ed.gov/sites/default/files/2026-05/FrequentlyAskedQuestionsLoanLimits.pdf" target="_blank" rel="noopener noreferrer">Loan-limit details ↗</a></p><p>Borrowing does not reduce the price. The lifestyle picture assumes no loan payment until you add one.</p></div></details>`;}
